inline void write_vertex_list_support2_d(flight::SequenceView<double> vertices, double count, double dir_x, double dir_y, flight::Array<double> out) {
  double best_x = vertices[0.0];
  double best_y = vertices[1.0];
  double best = ((best_x * dir_x) + (best_y * dir_y));
  {
    double i = 1.0;
    while ((i < count)) {
      {
        const double x = vertices[(i * 2.0)];
        const double y = vertices[((i * 2.0) + 1.0)];
        const double projection = ((x * dir_x) + (y * dir_y));
        if ((projection > best)) {
          (best = projection);
          (best_x = x);
          (best_y = y);
        }
      }
      (i += 1.0);
    }
  }
  (out.element(0.0) = best_x);
  (out.element(1.0) = best_y);
}


